from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f"missing patch anchor in {path}: {old[:100]!r}")
    p.write_text(text.replace(old, new, 1))

# sensor.py imports + entity registration.
replace_once(
    "custom_components/dummy_os_data/sensor.py",
    "from .model_health import calculate_model_health_readiness\n",
    "from .model_health import calculate_model_health_readiness\nfrom .forecast_planner_contract import build_forecast_planner_contract\n",
)
replace_once(
    "custom_components/dummy_os_data/sensor.py",
    "            DummyOSEnergyForecastPlannerHoursSensor(coordinator),\n            DummyOSHomeForecastNextQuarterSensor(coordinator),\n",
    "            DummyOSEnergyForecastPlannerHoursSensor(coordinator),\n            DummyOSEnergyForecastPlannerContractSensor(coordinator),\n            DummyOSHomeForecastNextQuarterSensor(coordinator),\n",
)

# Shared Step 14 helper used by both Step 14 sensor and Step 15 contract.
anchor = '''class DummyOSEnergyForecastPlannerHoursSensor(DummyOSBaseSensor):\n'''
helper = '''def _build_planner_hours_result(\n    coordinator: DummyOSHomeDataCoordinator,\n    *,\n    now: datetime | None = None,\n) -> dict[str, Any]:\n    reference = now or dt_util.utcnow()\n    model = HomeBaselineForecast(coordinator.records)\n    public_slots = model.build(coordinator.profile, now=reference)\n    if not public_slots:\n        return aggregate_planner_hours(\n            [], profile=coordinator.profile, localize=dt_util.as_local\n        )\n    generated_count = required_generated_slot_count(\n        public_slots[0].start, dt_util.as_local\n    )\n    extended_slots = model.build(\n        coordinator.profile, now=reference, slot_count=generated_count\n    )\n    result = aggregate_planner_hours(\n        extended_slots, profile=coordinator.profile, localize=dt_util.as_local\n    )\n    if coordinator.profile not in PROFILE_LEARNING_OPTIONS:\n        result[\"status\"] = \"profile_unclassified\"\n    return result\n\n\n'''
replace_once("custom_components/dummy_os_data/sensor.py", anchor, helper + anchor)
old_result = '''    def _result(self) -> dict[str, Any]:\n        now = dt_util.utcnow()\n        model = HomeBaselineForecast(self.coordinator.records)\n        public_slots = model.build(self.coordinator.profile, now=now)\n        if not public_slots:\n            return aggregate_planner_hours(\n                [], profile=self.coordinator.profile, localize=dt_util.as_local\n            )\n        generated_count = required_generated_slot_count(\n            public_slots[0].start, dt_util.as_local\n        )\n        extended_slots = model.build(\n            self.coordinator.profile, now=now, slot_count=generated_count\n        )\n        result = aggregate_planner_hours(\n            extended_slots, profile=self.coordinator.profile, localize=dt_util.as_local\n        )\n        if not self._profile_learnable:\n            result[\"status\"] = \"profile_unclassified\"\n        return result\n'''
new_result = '''    def _result(self) -> dict[str, Any]:\n        return _build_planner_hours_result(self.coordinator)\n'''
replace_once("custom_components/dummy_os_data/sensor.py", old_result, new_result)

# Shared Step 13 helper so Step 15 consumes the same readiness result.
health_anchor = '''class DummyOSHomeForecastModelHealthSensor(DummyOSBaseSensor):\n'''
health_helper = '''def _build_model_health_result(\n    coordinator: DummyOSHomeDataCoordinator,\n    slots: list[Any],\n) -> dict[str, Any]:\n    supported = sum(1 for slot in slots if slot.source in SUPPORTED_SOURCES)\n    coverage = round(supported / len(slots) * 100, 1) if slots else None\n    confidence = HomeBaselineForecast.average_confidence(slots)\n    metrics = coordinator.evaluation_metrics(coordinator.profile)\n    horizon_quality = calculate_horizon_quality(\n        coordinator.horizon_daily_stats,\n        coordinator.profile,\n    )\n    day_type_daypart_quality = calculate_day_type_daypart_quality(\n        coordinator.evaluations,\n        coordinator.records,\n        coordinator.profile,\n        dt_util.as_local,\n    )\n    hour_quality = calculate_hour_quality(\n        coordinator.evaluations,\n        coordinator.records,\n        coordinator.profile,\n        dt_util.as_local,\n    )\n    return calculate_model_health_readiness(\n        records=coordinator.records,\n        profile=coordinator.profile,\n        source_available=coordinator.source_available,\n        forecast_coverage_percent=coverage,\n        average_confidence_percent=confidence,\n        evaluation_metrics=metrics,\n        horizon_quality=horizon_quality,\n        day_type_daypart_quality=day_type_daypart_quality,\n        hour_quality=hour_quality,\n        localize=dt_util.as_local,\n    )\n\n\n'''
replace_once("custom_components/dummy_os_data/sensor.py", health_anchor, health_helper + health_anchor)
old_health = '''    def _readiness(self) -> dict[str, Any]:\n        slots = self._forecast()\n        supported = sum(1 for slot in slots if slot.source in SUPPORTED_SOURCES)\n        coverage = round(supported / len(slots) * 100, 1) if slots else None\n        confidence = HomeBaselineForecast.average_confidence(slots)\n        metrics = self.coordinator.evaluation_metrics(self.coordinator.profile)\n        horizon_quality = calculate_horizon_quality(\n            self.coordinator.horizon_daily_stats,\n            self.coordinator.profile,\n        )\n        day_type_daypart_quality = calculate_day_type_daypart_quality(\n            self.coordinator.evaluations,\n            self.coordinator.records,\n            self.coordinator.profile,\n            dt_util.as_local,\n        )\n        hour_quality = calculate_hour_quality(\n            self.coordinator.evaluations,\n            self.coordinator.records,\n            self.coordinator.profile,\n            dt_util.as_local,\n        )\n        return calculate_model_health_readiness(\n            records=self.coordinator.records,\n            profile=self.coordinator.profile,\n            source_available=self.coordinator.source_available,\n            forecast_coverage_percent=coverage,\n            average_confidence_percent=confidence,\n            evaluation_metrics=metrics,\n            horizon_quality=horizon_quality,\n            day_type_daypart_quality=day_type_daypart_quality,\n            hour_quality=hour_quality,\n            localize=dt_util.as_local,\n        )\n'''
new_health = '''    def _readiness(self) -> dict[str, Any]:\n        return _build_model_health_result(self.coordinator, self._forecast())\n'''
replace_once("custom_components/dummy_os_data/sensor.py", old_health, new_health)

# Step 15 sensor after planner-hours sensor.
contract_anchor = '''class DummyOSHomeForecastNextQuarterSensor(DummyOSBaseSensor):\n'''
contract_class = '''class DummyOSEnergyForecastPlannerContractSensor(DummyOSBaseSensor):\n    \"\"\"Stable Step 15 Forecast -> Planner contract.\"\"\"\n\n    _attr_name = \"DO Energy Forecast Planner Contract\"\n    _attr_unique_id = \"do_energy_forecast_planner_contract\"\n    _attr_suggested_object_id = \"do_energy_forecast_planner_contract\"\n    _attr_icon = \"mdi:connection\"\n    _unrecorded_attributes = frozenset({\"hours\"})\n\n    def _result(self) -> dict[str, Any]:\n        now = dt_util.utcnow()\n        planner_hours = _build_planner_hours_result(self.coordinator, now=now)\n        model = HomeBaselineForecast(self.coordinator.records)\n        slots = model.build(self.coordinator.profile, now=now)\n        model_health = _build_model_health_result(self.coordinator, slots)\n        return build_forecast_planner_contract(\n            planner_hours=planner_hours,\n            model_health=model_health,\n        )\n\n    @property\n    def native_value(self) -> str:\n        return str(self._result()[\"status\"])\n\n    @property\n    def extra_state_attributes(self) -> dict[str, Any]:\n        return dict(self._result())\n\n\n'''
replace_once("custom_components/dummy_os_data/sensor.py", contract_anchor, contract_class + contract_anchor)

# Entity-ID aliases and canonical migration.
replace_once(
    "custom_components/dummy_os_data/entity_migrations.py",
    '    "do_energy_forecast_planner_hours": "sensor.dummy_os_forecast_do_energy_forecast_planner_hours",\n',
    '    "do_energy_forecast_planner_hours": "sensor.dummy_os_forecast_do_energy_forecast_planner_hours",\n    "do_energy_forecast_planner_contract": "sensor.dummy_os_forecast_do_energy_forecast_planner_contract",\n',
)
replace_once(
    "custom_components/dummy_os_data/__init__.py",
    '    ("sensor", "do_energy_forecast_planner_hours", "sensor.do_energy_forecast_planner_hours"),\n',
    '    ("sensor", "do_energy_forecast_planner_hours", "sensor.do_energy_forecast_planner_hours"),\n    ("sensor", "do_energy_forecast_planner_contract", "sensor.do_energy_forecast_planner_contract"),\n',
)

# Pure contract tests.
Path("tests/test_forecast_planner_contract.py").write_text('''from datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nimport importlib.util\n\nMODULE_PATH = Path(__file__).parents[1] / "custom_components/dummy_os_data/forecast_planner_contract.py"\nSPEC = importlib.util.spec_from_file_location("forecast_planner_contract", MODULE_PATH)\nassert SPEC is not None and SPEC.loader is not None\nMODULE = importlib.util.module_from_spec(SPEC)\nSPEC.loader.exec_module(MODULE)\n\ndef hours():\n    start = datetime(2026, 9, 7, 20, 0, tzinfo=timezone.utc)\n    out = []\n    for i in range(72):\n        s = start + timedelta(hours=i)\n        out.append({\n            "index": i,\n            "start": s.isoformat(),\n            "end": (s + timedelta(hours=1)).isoformat(),\n            "energy_kwh": 0.4,\n            "quarter_count": 4,\n            "populated_quarters": 4,\n            "supported_quarters": 4,\n            "minimum_confidence": 0.66,\n            "average_confidence": 0.72,\n            "source_distribution": {"weekday_quarter": 4},\n            "profile": "normal",\n        })\n    return out\n\ndef planner(**overrides):\n    base = {\n        "status": "ok",\n        "profile": "normal",\n        "native_resolution_minutes": 15,\n        "native_public_slots": 288,\n        "planner_hour_count": 72,\n        "valid_hour_count": 72,\n        "quarters_per_hour": 4,\n        "planner_start": "2026-09-07T20:00:00+00:00",\n        "planner_end": "2026-09-10T20:00:00+00:00",\n        "leading_quarter_offset": 2,\n        "extra_quarters_generated": 2,\n        "generated_quarter_count": 290,\n        "padding_used": False,\n        "second_forecast_architecture": False,\n        "hours": hours(),\n    }\n    base.update(overrides)\n    return base\n\ndef health(status="usable", **overrides):\n    base = {\n        "profile": "normal",\n        "readiness_status": status,\n        "history_days": 14,\n        "valid_quarters": 1140,\n        "forecast_coverage_percent": 100.0,\n        "average_confidence_percent": 71.4,\n        "evaluation_samples": 1116,\n        "accuracy_percent": 47.4,\n        "mae_kwh": 0.072587,\n        "bias_kwh": -0.000444,\n        "absolute_bias_kwh": 0.000444,\n        "horizon_evidence_status": "collecting",\n        "runtime_input_status": "source_unavailable",\n        "forecast_operational_input_ok": False,\n        "runtime_blockers": ["source_unavailable"],\n    }\n    base.update(overrides)\n    return base\n\ndef test_ready_contract_accepts_usable_even_if_runtime_source_unavailable():\n    result = MODULE.build_forecast_planner_contract(planner_hours=planner(), model_health=health())\n    assert result["status"] == "ready"\n    assert result["ready_for_planner"] is True\n    assert result["blockers"] == []\n    assert result["contract_name"] == "dummy_os_forecast_to_planner"\n    assert result["contract_version"] == 1\n    assert result["schema_version"] == 1\n    assert result["native_slot_count"] == 288\n    assert result["planner_hour_count"] == 72\n    assert result["quarters_per_hour"] == 4\n    assert result["forecast_operational_input_ok"] is False\n    assert len(result["hours"]) == 72\n\ndef test_learning_model_health_blocks_contract():\n    result = MODULE.build_forecast_planner_contract(planner_hours=planner(), model_health=health("learning"))\n    assert result["status"] == "blocked"\n    assert result["ready_for_planner"] is False\n    assert "model_health_learning" in result["blockers"]\n\ndef test_padding_or_partial_hour_blocks_contract():\n    p = planner(padding_used=True)\n    p["hours"][5]["energy_kwh"] = None\n    p["hours"][5]["populated_quarters"] = 3\n    result = MODULE.build_forecast_planner_contract(planner_hours=p, model_health=health())\n    assert result["status"] == "blocked"\n    assert "padding_detected" in result["blockers"]\n    assert "hour_5_not_fully_populated" in result["blockers"]\n    assert "hour_5_energy_unavailable" in result["blockers"]\n\ndef test_unclassified_profile_is_explicit():\n    result = MODULE.build_forecast_planner_contract(\n        planner_hours=planner(profile="unclassified", status="profile_unclassified"),\n        model_health=health(profile="unclassified", readiness_status="profile_unclassified"),\n    )\n    assert result["status"] == "profile_unclassified"\n    assert result["ready_for_planner"] is False\n    assert "profile_unclassified" in result["blockers"]\n\ndef test_wrong_window_and_second_architecture_are_blocked():\n    result = MODULE.build_forecast_planner_contract(\n        planner_hours=planner(\n            planner_end="2026-09-10T19:00:00+00:00",\n            second_forecast_architecture=True,\n        ),\n        model_health=health(),\n    )\n    assert "planner_window_not_72h" in result["blockers"]\n    assert "second_forecast_architecture_detected" in result["blockers"]\n''')

Path("tests/test_forecast_planner_contract_sensor.py").write_text('''from pathlib import Path\n\nROOT = Path(__file__).parents[1]\nSENSOR = (ROOT / "custom_components/dummy_os_data/sensor.py").read_text()\nINIT = (ROOT / "custom_components/dummy_os_data/__init__.py").read_text()\nMIGRATIONS = (ROOT / "custom_components/dummy_os_data/entity_migrations.py").read_text()\nCONTRACT = (ROOT / "custom_components/dummy_os_data/forecast_planner_contract.py").read_text()\nFORECAST = (ROOT / "custom_components/dummy_os_data/forecast.py").read_text()\n\ndef test_step15_canonical_sensor_and_registry_route():\n    assert '_attr_name = "DO Energy Forecast Planner Contract"' in SENSOR\n    assert '_attr_unique_id = "do_energy_forecast_planner_contract"' in SENSOR\n    assert '_attr_suggested_object_id = "do_energy_forecast_planner_contract"' in SENSOR\n    assert 'DummyOSEnergyForecastPlannerContractSensor(coordinator)' in SENSOR\n    assert '("sensor", "do_energy_forecast_planner_contract", "sensor.do_energy_forecast_planner_contract")' in INIT\n    assert '"do_energy_forecast_planner_contract": "sensor.dummy_os_forecast_do_energy_forecast_planner_contract"' in MIGRATIONS\n\ndef test_step15_uses_shared_step13_and_step14_results():\n    assert 'def _build_planner_hours_result(' in SENSOR\n    assert 'def _build_model_health_result(' in SENSOR\n    assert 'build_forecast_planner_contract(' in SENSOR\n    assert 'return _build_planner_hours_result(self.coordinator)' in SENSOR\n    assert 'return _build_model_health_result(self.coordinator, self._forecast())' in SENSOR\n\ndef test_step15_contract_is_versioned_and_model_agnostic():\n    assert 'CONTRACT_NAME = "dummy_os_forecast_to_planner"' in CONTRACT\n    assert 'CONTRACT_VERSION = 1' in CONTRACT\n    assert 'SCHEMA_VERSION = 1' in CONTRACT\n    assert 'NATIVE_SLOT_COUNT = 288' in CONTRACT\n    assert 'PLANNER_HOUR_COUNT = 72' in CONTRACT\n    assert 'physical_execution_authority": False' in CONTRACT\n    assert 'fallback_hierarchy' not in CONTRACT\n    assert 'RECENCY_HALF_LIFE_DAYS' not in CONTRACT\n\ndef test_native_forecast_contract_remains_step14_default():\n    assert 'slot_count: int = FORECAST_SLOTS' in FORECAST\n    assert 'MAX_INTERNAL_FORECAST_SLOTS = FORECAST_SLOTS + 3' in FORECAST\n    assert 'RECENCY_HALF_LIFE_DAYS = 28.0' in FORECAST\n''')
